import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-backup', 'backup@corp.internal', 'service', 'sk-svc-1a2b3c4d', 'ops')")
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['department', 'role', 'username', 'email']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with validated field name but injectable value
    query = f"SELECT id, username, email, role, department FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        actor = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute("INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
                   ('user_search', actor, f"{field}={value}"))
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>/keys', methods=['GET'])
def get_user_keys(user_id):
    """Retrieve API keys for a user. Requires admin role."""
    requesting_user = request.headers.get('X-Authenticated-User', '')
    db = get_db()

    # Check if requesting user is admin
    admin_check = db.execute(
        "SELECT role FROM users WHERE username = ?", (requesting_user,)
    ).fetchone()

    if not admin_check or admin_check['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    user = db.execute(
        "SELECT id, username, api_key FROM users WHERE id = ?", (user_id,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Not found'}), 404

    return jsonify({'user_id': user['id'], 'username': user['username'], 'api_key': user['api_key']})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
